import { useErrorBoundary } from '@suspensive/react';
import { InfiniteData, useSuspenseInfiniteQuery } from '@tanstack/react-query';
import { VoucherListResponseDTO, VoucherListRequestDTO } from '~/entities/voucher/api/dtos/voucher-list';
import { voucherApi } from '~/entities/voucher/api/voucher-api';
import { DEFAULT_VOUCHER_PAGING } from '~/entities/voucher/model/constants';
import { DEFAULT_HISTORY_PAGE_SIZE } from '~/entities/wallet/api/dtos/constants';
import { CBDCAxiosError } from '~/shared/@types/error';
import { InfiniteQueryOptions } from '~/shared/@types/query';
import { queries } from '~/shared/api/query-keys';
import i18n from '~/shared/i18n/i18n';

type IssuedVoucherListQueryParams = VoucherListRequestDTO & {
  cstmrNo?: string | null;
  userAliasNm?: string | null;
};

export const useIssuedVoucherListInfiniteQuery = (
  params: IssuedVoucherListQueryParams,
  options?: InfiniteQueryOptions<
    VoucherListResponseDTO,
    CBDCAxiosError,
    InfiniteData<VoucherListResponseDTO>,
    readonly unknown[],
    IssuedVoucherListQueryParams
  >,
) => {
  const { paging = DEFAULT_VOUCHER_PAGING, search, aliasNm, cstmrNo, userAliasNm } = params;
  const { setError } = useErrorBoundary();
  if (!paging) {
    setError(new Error(i18n.t('validation:temporaryErrorOccurred')));
  }

  return useSuspenseInfiniteQuery<
    VoucherListResponseDTO,
    CBDCAxiosError,
    InfiniteData<VoucherListResponseDTO>,
    readonly unknown[],
    IssuedVoucherListQueryParams
  >({
    queryKey: queries.voucher.issuedVoucherList({ paging, search, aliasNm, cstmrNo, userAliasNm }).queryKey,
    queryFn: ({ pageParam = { paging, search, aliasNm, cstmrNo, userAliasNm } }) =>
      voucherApi.getIssuedVoucherList({
        paging: pageParam.paging,
        search: pageParam.search,
        aliasNm: pageParam.aliasNm,
      }),
    gcTime: 1000 * 60 * 5,
    refetchOnMount: 'always',
    refetchOnWindowFocus: true,
    refetchOnReconnect: true,
    initialPageParam: { paging, search, aliasNm },
    getNextPageParam: (lastPage) => {
      const currentListLength = lastPage?.result?.list?.length ?? 0;
      const currentPageNo = lastPage?.result?.paging?.currentPageNo;

      // aliasNm=ALL 응답은 walletList 중심 구조라 paging/list 기반 infinite scroll을 사용하지 않는다.
      if (!currentPageNo || currentListLength < DEFAULT_HISTORY_PAGE_SIZE) {
        return undefined;
      }
      return {
        paging: {
          ...paging,
          currentPageNo: currentPageNo + 1,
        },
        search,
        aliasNm,
        cstmrNo,
        userAliasNm,
      };
    },
    // staleTime: 1000 * 60,
    staleTime: 0,
    ...options,
  });
};
